package render

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"regexp"
	"sort"
	"strings"

	"github.com/brioly/brioly/pkg/facts"
)

// Unverified replaces a citation of a fact ID that does not exist, in an
// English document.
const Unverified = "⚠️ *(unverified)*"

// wording is the text code adds to a model-written document: it follows
// the language the model was asked to write in. The source list itself
// (kinds, names, references) reads the same in every language, like the
// documents generated by code.
type wording struct {
	unverified string // replaces a citation of nothing
	sources    string // heads the source list of a published document
	writtenBy  string // first line; %s is who wrote it
	unknown    string // added to it; %d is how many citations name nothing
}

var wordings = map[string]wording{
	"English": {
		unverified: Unverified,
		sources:    "Sources (internal — remove before publishing)",
		writtenBy:  "Written by %s from collected facts. Each statement cites its source; inferences are marked as such.",
		unknown:    "%d statement(s) cite sources that do not exist and are marked unverified.",
	},
	"Korean": {
		unverified: "⚠️ *(확인되지 않음)*",
		sources:    "출처 (내부용 — 게시 전에 삭제하세요)",
		writtenBy:  "수집된 사실을 바탕으로 작성된 문서입니다(작성: %s). 서술마다 출처를 인용했고, 추론한 내용은 추론이라고 표시했습니다.",
		unknown:    "존재하지 않는 출처를 인용한 서술 %d개는 확인되지 않음으로 표시했습니다.",
	},
	"Japanese": {
		unverified: "⚠️ *(未確認)*",
		sources:    "出典(社内用 — 公開前に削除してください)",
		writtenBy:  "収集された事実をもとに作成された文書です(作成: %s)。各記述には出典を引用し、推論した内容は推論と明記しています。",
		unknown:    "存在しない出典を引用した記述が%d件あり、未確認と表示しています。",
	},
}

// wordingFor returns the wording of a language as enrich.Options names it;
// a language without one reads in English.
func wordingFor(language string) wording {
	if w, ok := wordings[language]; ok {
		return w
	}
	return wordings["English"]
}

var citation = regexp.MustCompile(`\[\[([^\[\]]+)\]\]`)

// Document is a model-written document to resolve.
type Document struct {
	Path     string // relative to the output directory
	Markdown string
	// Published documents (job descriptions) are read outside the company:
	// their source list is marked as internal.
	Published bool
	// Language the model wrote in, as given to enrich ("English", "Korean",
	// "Japanese"): the text added by Written follows it. Empty, or a
	// language without a wording, is English.
	Language string
}

// ResolveCitations turns [[id]] markers (fact, component or note IDs) into
// Markdown footnotes that point to each source. Citations of unknown IDs
// are replaced with an "unverified" marker. It returns the resolved text
// and the number of unknown citations.
func ResolveCitations(md string, s *facts.Snapshot, published bool) (string, int) {
	return resolveCitations(md, s, published, wordingFor(""))
}

func resolveCitations(md string, s *facts.Snapshot, published bool, w wording) (string, int) {
	// Footnotes quote names and references: they are written from the
	// escaped copy, like every other document.
	if text, err := escaped(s); err == nil {
		s = text
	}
	g := newGraph(s)
	notes := map[string]facts.Annotation{}
	for _, a := range s.Annotations {
		notes[a.ID] = a
	}
	source := func(id string) (string, bool) {
		if f, ok := g.byID[id]; ok {
			return fmt.Sprintf("%s **%s** — %s", f.Kind, mdEscape(displayName(f)), evidence(f)), true
		}
		if c, ok := s.ComponentByID(id); ok {
			return fmt.Sprintf("Component **%s** (%s), identified by %s", mdEscape(c.Name), c.Role, evidence(g.byID[c.Anchor])), true
		}
		if a, ok := notes[strings.TrimPrefix(id, "note:")]; ok {
			by := ""
			if a.Author != "" {
				by = " by " + a.Author
			}
			return fmt.Sprintf("Team note%s: \"%s\"", by, mdEscape(a.Body)), true
		}
		return "", false
	}

	// A footnote's label comes from the ID it cites, not from its position:
	// numbered labels would shift through the whole document whenever one
	// citation is added, and bury the real change in the diff. Markdown
	// viewers show footnotes as numbers either way.
	labels := map[string]string{}
	var order, footnotes []string
	unknown := 0
	body := citation.ReplaceAllStringFunc(md, func(m string) string {
		id := strings.TrimSpace(citation.FindStringSubmatch(m)[1])
		l, seen := labels[id]
		if !seen {
			text, ok := source(id)
			if !ok {
				unknown++
				return w.unverified
			}
			l = FootnoteLabel(id)
			labels[id] = l
			order = append(order, l)
			footnotes = append(footnotes, text)
		}
		return "[^" + l + "]"
	})
	if len(footnotes) == 0 {
		return body, unknown
	}
	var b strings.Builder
	b.WriteString(strings.TrimRight(body, "\n"))
	if published {
		b.WriteString("\n\n---\n\n**" + w.sources + "**\n\n")
	} else {
		b.WriteString("\n\n---\n\n")
	}
	// Sorted by label, so a new source adds one line and moves none.
	idx := make([]int, len(order))
	for i := range idx {
		idx[i] = i
	}
	sort.Slice(idx, func(a, c int) bool { return order[idx[a]] < order[idx[c]] })
	for _, i := range idx {
		fmt.Fprintf(&b, "[^%s]: %s\n", order[i], footnotes[i])
	}
	return b.String(), unknown
}

// FootnoteLabel is the label of the footnote a citation of the ID becomes
// in a written document: "[[id]]" is written as "[^label]". Short, and the
// same for the same ID in every document, so a caller can find where a
// stored document cites a fact or a component.
func FootnoteLabel(id string) string {
	sum := sha256.Sum256([]byte(id))
	return hex.EncodeToString(sum[:])[:6]
}

// Written returns a model-written document as it is published: its
// citations resolved against s, under a line that says who wrote it. The
// second result is the number of citations that name nothing in s.
func Written(s *facts.Snapshot, d Document, producer string) (string, int) {
	w := wordingFor(d.Language)
	text, unknown := resolveCitations(d.Markdown, s, d.Published, w)
	header := "> " + fmt.Sprintf(w.writtenBy, producer)
	if unknown > 0 {
		header += " " + fmt.Sprintf(w.unknown, unknown)
	}
	return header + "\n\n" + strings.TrimSpace(text) + "\n", unknown
}

var nonSlug = regexp.MustCompile(`[^\p{L}\p{N}]+`)

// Slug turns a role title into a file name. Letters and digits of every
// script are kept, so "백엔드 엔지니어" and "프론트엔드 엔지니어" stay
// distinct.
func Slug(s string) string {
	slug := strings.Trim(nonSlug.ReplaceAllString(strings.ToLower(s), "-"), "-")
	if slug == "" {
		return "role"
	}
	return slug
}

// UniquePath returns name with a numeric suffix if it is already in used,
// and records the result.
func UniquePath(used map[string]bool, dir, name, ext string) string {
	p := dir + name + ext
	for i := 2; used[p]; i++ {
		p = fmt.Sprintf("%s%s-%d%s", dir, name, i, ext)
	}
	used[p] = true
	return p
}
